166	  TF_RETURN_IF_ERROR(InitGraph(graph_def, config, &graph));
167	  TF_RETURN_IF_ERROR(
168	      ConvertGraphToXla(std::move(graph), config, client, computation));
169	  return absl::OkStatus();
170	}
