28	// TensorId identifies a tensor in a TensorFlow graph, by specifying the output
29	// index of a particular node in the graph.  If the output of the named node
30	// feeds into other node(s), this corresponds to one or more edges.  Otherwise
31	// it doesn't correspond to any existing edges at all, e.g. for output nodes.
32	message TensorId {
33	  string node_name = 1;
34	  int64 output_index = 2;
35	}
36	
37	// Feed represents a single feed tensor in the graph, which corresponds to an
38	// input argument for the generated computation.
39	message Feed {
40	  TensorId id = 1;
41	  TensorShapeProto shape = 2;
42	  string name = 3;  // Optional name for generated code.
43	
44	  // Optional data type. This is not normally required, as the graph itself
45	  // contains this information. However, if the node being fed is an op that is
46	  // not linked into the binary, then the type cannot be inferred from the node;
47	  // in this case, the type should be set here.
48	  DataType type = 4;
49	}
50	
51	// Fetch represents a single fetch tensor in the graph, which corresponds to an
52	// output argument for the generated computation.
53	message Fetch {
54	  TensorId id = 1;
55	  string name = 2;  // Optional name for generated code.
56	
57	  // Optional shape and data type. If specified, may be used for validation.
58	  TensorShapeProto shape = 3;
59	  DataType type = 4;
60	}
61	
62	// Variable represents a resource variable with the given name, shape and type.
63	message Variable {
64	  string node_name = 1;
65	  string name =
66	      2;  // Optional name for generated code. If empty, node_name will be used.
67	  TensorShapeProto shape = 3;
68	  DataType type = 4;
69	
70	  // Flag for variables that are never assigned. Assignments to a read-only
71	  // variable or unassigned variables that are not read-only are invalid.
72	  bool readonly = 5;
73	}
74	
75	// Config represents configuration information for tf2xla conversion.
76	message Config {
77	  // Each feed is a positional input argument for the generated computation.
78	  // The order of each entry matches the order of each input argument.
79	  repeated Feed feed = 1;
80	  // Each fetch is a positional output argument for the generated computation.
81	  // The order of each entry matches the order of each output argument.
82	  repeated Fetch fetch = 2;
83	  // Each variable is a named input and output of the generated computation.
84	  repeated Variable variable = 3;
85	}
